"""Scoped calendars, publication and notification UI; Google/MailApp emulated."""
import importlib.util,json,unittest,tomllib
from pathlib import Path
from urllib.parse import urlsplit
from playwright.sync_api import expect
spec=importlib.util.spec_from_file_location('staff_qa',Path(__file__).with_name('test-staff.py'));qa=importlib.util.module_from_spec(spec);spec.loader.exec_module(qa)
ROOT,ORIGIN=qa.qa.ROOT,qa.qa.ORIGIN
class Schedules(qa.Staff):
    def setUp(self):
        super().setUp();self.lose_schedule=None;self.schedule_commands=[]
    def relay(self,route):
        req=route.request;path=urlsplit(req.url).path
        if path in ['/escalas-dev.html','/escalas-dev.js','/escalas-dev.css','/account-menu.js','/account-menu.css','/notificacoes-dev.html','/notificacoes-dev.js','/notificacoes-dev.css','/notification-badge.js']:
            headers={}
            for rule in tomllib.loads((ROOT/'netlify.toml').read_text()).get('headers',[]):
                if rule['for']==path:headers.update(rule['values'])
            route.fulfill(status=200,content_type={'.html':'text/html','.js':'application/javascript','.css':'text/css'}[Path(path).suffix],headers=headers,body=(ROOT/'dist'/path[1:]).read_bytes());return
        if path.startswith(('/api/v1/schedules/','/api/v1/notifications/','/api/v1/profile/')):
            headers={k:v for k,v in req.all_headers().items() if k not in ['host','content-length']};query=urlsplit(req.url).query;out=self.local(path+('?' + query if query else ''),body=req.post_data_buffer,headers=headers,method=req.method)
            if path.startswith('/api/v1/schedules/') and req.method=='POST':
                self.schedule_commands.append(json.loads(req.post_data))
                if self.lose_schedule==path.rsplit('/',1)[-1]:self.lose_schedule=None;route.abort();return
            route.fulfill(status=out['status'],headers=out['headers'],body=out['body']);return
        super().relay(route)
    def schedules(self):
        self.team();self.fill();self.save_staff();self.local('/test/enable-schedules',{});self.page.goto(ORIGIN+'/escalas-dev.html?data=2026-11-10');expect(self.page.locator('#schedule')).to_be_visible()
    def fill_shift(self,notes='Preparar a abertura com cuidado'):
        self.page.locator('#new-shift').click();expect(self.page.locator('#shift-editor')).to_be_visible();self.page.locator('#shift-employee').select_option(label='Pessoa de teste');self.page.locator('#shift-date').fill('2026-11-10');self.page.locator('#shift-start').fill('09:00');self.page.locator('#shift-end').fill('12:00');self.page.locator('#shift-notes').fill(notes)
    def publish(self):
        self.page.locator('#publish-shift').click();expect(self.page.locator('#shift-editor')).not_to_be_visible();expect(self.page.locator('.shift')).to_have_count(1)
    def staff_login(self):
        self.page.goto(ORIGIN+'/acesso-dev.html?verificar=1');expect(self.page.locator('#complete')).to_be_visible();self.logout();self.page.get_by_text('É meu primeiro acesso',exact=True).click();self.page.locator('#activation-email').fill('52998224725');self.page.get_by_role('button',name='Receber código por e-mail').click();expect(self.page.locator('#email-form')).to_be_visible();self.page.locator('#email-code').fill(self.local('/test/code')['code']);self.page.get_by_role('button',name='Confirmar código').click();expect(self.page.locator('#pin-form')).to_be_visible();self.page.locator('#new-pin').fill('9382');self.page.locator('#confirm-pin').fill('9382');self.page.get_by_role('button',name='Salvar PIN e continuar').click();expect(self.page.locator('#passkey')).to_be_visible();self.page.locator('#passkey-button').click();expect(self.page.locator('#complete')).to_be_visible()
    def test_schedules_mobile_week_month_private_details_and_internal_notification(self):
        self.schedules();self.cdp.send('Emulation.setTimezoneOverride',{'timezoneId':'Pacific/Honolulu'});self.fill_shift();self.publish();self.page.locator('#month-view').click();expect(self.page.locator('#calendar')).to_have_class('month-grid');expect(self.page.locator('.day')).to_have_count(42);expect(self.page.locator('.day[data-date="2026-11-10"] .shift')).to_have_count(1);self.assertTrue(self.page.evaluate('document.documentElement.scrollWidth<=innerWidth'));self.staff_login();self.page.goto(ORIGIN+'/escalas-dev.html?data=2026-11-10');expect(self.page.locator('.shift')).to_have_count(1);expect(self.page.locator('#new-shift')).to_be_hidden();self.page.locator('.shift').click();expect(self.page.locator('#shift-notes')).to_have_value('Preparar a abertura com cuidado');expect(self.page.locator('#shift-notes')).to_be_disabled();expect(self.page.locator('#publish-shift')).to_be_hidden();expect(self.page.locator('#publisher')).to_contain_text('Publicado por');self.page.locator('#close-editor').click()
        self.page.locator('.account-menu summary').click();expect(self.page.get_by_role('link',name='Minha escala',exact=True)).to_be_visible();self.page.goto(ORIGIN+'/notificacoes-dev.html');expect(self.page.locator('.alert')).to_have_count(1);expect(self.page.locator('.alert')).to_contain_text('Escala publicada');expect(self.page.get_by_role('link',name='Adicionar unidades')).to_have_count(0);self.page.get_by_role('button',name='Marcar como lida').click();expect(self.page.locator('.alert')).to_have_count(0);self.page.locator('#history').check();expect(self.page.locator('.alert')).to_have_count(1);self.assert_no_secrets_in_browser_storage();self.assertEqual(self.errors,[])
        self.page.goto(ORIGIN+'/escalas-dev.html?data=2026-11-10');expect(self.page.locator('.shift')).to_have_count(1);target=ROOT/'work/qa-schedules';target.mkdir(parents=True,exist_ok=True);self.page.screenshot(path=str(target/'minha-escala-celular.png'),full_page=True)
    def test_schedules_draft_hidden_then_publish_edit_and_cancel_preserves_history(self):
        self.schedules();self.fill_shift('Nota privada do rascunho');self.page.locator('#save-draft').click();expect(self.page.locator('#shift-editor')).not_to_be_visible();expect(self.page.locator('.shift')).to_contain_text('Rascunho');self.page.locator('.shift').click();self.publish();expect(self.page.locator('.shift')).to_contain_text('Publicada');self.page.locator('.shift').click();self.page.locator('#shift-end').fill('11:00');self.publish();expect(self.page.locator('.shift')).to_contain_text('09:00–11:00');self.page.locator('.shift').click();self.page.locator('#cancel-shift').click();expect(self.page.locator('#shift-editor')).not_to_be_visible();expect(self.page.locator('.shift')).to_contain_text('Cancelada');self.assertEqual(self.local('/test/schedule-state'),{'shifts':1,'events':3});self.assertEqual(self.errors,[])
    def test_schedules_lost_publication_ack_retries_exact_command_without_duplicate_event(self):
        self.schedules();self.fill_shift();self.lose_schedule='save';self.page.locator('#publish-shift').click();expect(self.page.locator('#retry-shift')).to_be_visible();expect(self.page.locator('#shift-notes')).to_be_disabled();expect(self.page.locator('#close-editor')).to_be_disabled();self.page.locator('#retry-shift').click();expect(self.page.locator('#shift-editor')).not_to_be_visible();expect(self.page.locator('.shift')).to_have_count(1);self.assertEqual(self.schedule_commands[0],self.schedule_commands[1]);self.assertEqual(self.local('/test/schedule-state'),{'shifts':1,'events':1});self.assert_no_secrets_in_browser_storage();self.assertEqual(self.errors,[])
    def test_schedules_overlapping_hours_keep_form_and_adjacent_hours_are_allowed(self):
        self.schedules();self.fill_shift();self.publish();self.fill_shift();self.page.locator('#shift-start').fill('10:00');self.page.locator('#shift-end').fill('11:00');self.page.locator('#publish-shift').click();expect(self.page.locator('#form-status')).to_contain_text('já tem uma escala');expect(self.page.locator('#shift-start')).to_be_enabled();self.page.locator('#shift-start').fill('12:00');self.page.locator('#shift-end').fill('13:00');self.page.locator('#publish-shift').click();expect(self.page.locator('#shift-editor')).not_to_be_visible();expect(self.page.locator('.shift')).to_have_count(2);self.assertEqual(self.errors,[])
    def test_schedules_calendar_refreshes_after_other_tab_changes_published_hours(self):
        self.schedules();self.fill_shift();self.publish();other=self.context.new_page();other.goto(ORIGIN+'/escalas-dev.html?data=2026-11-10');expect(other.locator('.shift')).to_have_count(1);other.locator('.shift').click();other.locator('#shift-end').fill('10:00');other.locator('#publish-shift').click();expect(other.locator('#shift-editor')).not_to_be_visible();self.page.evaluate("window.dispatchEvent(new Event('focus'))");expect(self.page.locator('.shift')).to_contain_text('09:00–10:00');other.close();self.assertEqual(self.errors,[])
    def test_schedules_attendant_sees_no_administrative_drafts(self):
        self.schedules();self.fill_shift('Não publicar');self.page.locator('#save-draft').click();expect(self.page.locator('#shift-editor')).not_to_be_visible();self.staff_login();self.page.goto(ORIGIN+'/escalas-dev.html?data=2026-11-10');expect(self.page.locator('#schedule')).to_be_visible();expect(self.page.locator('.shift')).to_have_count(0);expect(self.page.locator('#calendar')).not_to_contain_text('Não publicar');expect(self.page.locator('#new-shift')).to_be_hidden();self.assertEqual(self.errors,[])
if __name__=='__main__':
    suite=unittest.TestSuite(Schedules(name) for name in unittest.defaultTestLoader.getTestCaseNames(Schedules) if name.startswith('test_schedules_'));r=unittest.TextTestRunner(verbosity=2).run(suite);raise SystemExit(0 if r.wasSuccessful() else 1)
